import { GraphEdge } from './types';

export const edges: GraphEdge[] = [

  { id: 'e001', from: 'gobekli-tepe', to: 'younger-dryas', relationship_type: 'historical', strength_score: 0.7, explanation: 'Göbekli Tepe\'s construction phase (9600–8200 BCE) begins immediately after the Younger Dryas cooling period ends, raising questions about whether the resumption of warming and the end of the ice age created the conditions — or population pressures — that led to both monumental construction and the subsequent Agricultural Revolution.', evidence_basis: 'Radiocarbon dating of both events places them in the same millennium; multiple researchers have proposed a causal or contextual link.', source_type: 'archaeological', confidence_score: 0.65 },
  { id: 'e002', from: 'gobekli-tepe', to: 'ancient-megalithic-sites', relationship_type: 'historical', strength_score: 0.85, explanation: 'Göbekli Tepe is the earliest known example of the megalithic tradition and has prompted reassessment of the motivations and capabilities behind later megalithic construction worldwide. It demonstrates that monumental stone building for ritual purposes preceded agriculture, challenging the conventional developmental sequence.', evidence_basis: 'Archaeological: Göbekli Tepe predates all other known megalithic sites by several thousand years and shares key architectural features including circular arrangements and carved orthostats.', source_type: 'archaeological', confidence_score: 0.88 },
  { id: 'e003', from: 'gobekli-tepe', to: 'nabta-playa', relationship_type: 'thematic', strength_score: 0.55, explanation: 'Both Göbekli Tepe and Nabta Playa are pre-agricultural stone monuments with proposed astronomical alignments built by societies without full sedentary agriculture, challenging assumptions about the prerequisites for complex ritual architecture.', evidence_basis: 'Comparative archaeology; both sites are studied by researchers examining the origins of astronomical observation and monumental construction.', source_type: 'archaeological', confidence_score: 0.6 },
  { id: 'e004', from: 'gobekli-tepe', to: 'human-evolution', relationship_type: 'historical', strength_score: 0.75, explanation: 'Göbekli Tepe provides material evidence for the behavioral and cognitive capabilities of anatomically modern Homo sapiens approximately 10,000 years before writing, demonstrating that symbolic thought, organizational capacity, and aesthetic expression were fully developed long before civilization as conventionally defined.', evidence_basis: 'Archaeological: the site\'s sophisticated iconography, scale, and planning demonstrate cognitive modernity in its builders.', source_type: 'archaeological', confidence_score: 0.9 },
  { id: 'e005', from: 'atlantis', to: 'flood-narratives', relationship_type: 'thematic', strength_score: 0.8, explanation: 'Plato\'s account of Atlantis sinking "in a single day and night" is structurally parallel to flood mythology from multiple cultures. Some researchers have explored whether both Plato\'s Atlantis account and widespread flood myths reflect genuine catastrophic sea level events rather than purely literary invention.', evidence_basis: 'Textual: Plato\'s Timaeus and Critias; comparative mythology scholarship.', source_type: 'primary_text', confidence_score: 0.55 },
  { id: 'e006', from: 'atlantis', to: 'younger-dryas', relationship_type: 'thematic', strength_score: 0.5, explanation: 'Some researchers have proposed that the Younger Dryas impact event or the subsequent rapid sea level rise could provide a geological basis for the Atlantis narrative, which describes a civilization lost to catastrophic inundation.', evidence_basis: 'Speculative: geological data on post-glacial sea level rise is solid; its connection to the Atlantis narrative is interpretive rather than evidenced.', source_type: 'academic', confidence_score: 0.3 },
  { id: 'e007', from: 'atlantis', to: 'comparative-mythology', relationship_type: 'textual', strength_score: 0.7, explanation: 'Atlantis has been analyzed within comparative mythology as a variation on the widespread theme of a golden age civilization destroyed by divine punishment for hubris — present in Hesiod, Mesopotamian flood narratives, and Hindu Yugas.', evidence_basis: 'Classical scholarship: analysis of Plato\'s sources and the literary tradition in which Atlantis appears.', source_type: 'academic', confidence_score: 0.82 },
  { id: 'e008', from: 'sumerian-civilization', to: 'epic-of-gilgamesh', relationship_type: 'historical', strength_score: 0.99, explanation: 'The Epic of Gilgamesh originates directly from Sumerian literary traditions. Earlier Sumerian versions of individual episodes predating the Babylonian compilation are documented in cuneiform tablets. Gilgamesh himself is listed in the Sumerian King List as a historical ruler of Uruk.', evidence_basis: 'Primary textual evidence: cuneiform tablets from Ur, Nippur, and other Sumerian cities preserve earlier versions of the stories.', source_type: 'primary_text', confidence_score: 0.99 },
  { id: 'e009', from: 'sumerian-civilization', to: 'flood-narratives', relationship_type: 'textual', strength_score: 0.9, explanation: 'The Sumerian flood narrative — preserved in the Eridu Genesis and the Atra-Hasis epic — is among the oldest written flood accounts and predates the biblical narrative. Utnapishtim\'s flood story in Gilgamesh Tablet XI has direct parallels with Genesis.', evidence_basis: 'Primary textual: cuneiform tablets; comparative textual analysis of Near Eastern flood traditions.', source_type: 'primary_text', confidence_score: 0.95 },
  { id: 'e010', from: 'sumerian-civilization', to: 'ancient-astronaut-hypothesis', relationship_type: 'thematic', strength_score: 0.6, explanation: 'Zecharia Sitchin\'s ancient astronaut hypothesis is based primarily on his claimed interpretations of Sumerian cuneiform texts, particularly the Enuma Elish and the Sumerian King List, which he reinterpreted as describing extraterrestrial beings.', evidence_basis: 'Sitchin\'s works (The 12th Planet et al.); rejected by professional Sumerologists as mistranslation.', source_type: 'academic', confidence_score: 0.3 },
  { id: 'e011', from: 'great-pyramid', to: 'sphinx', relationship_type: 'geographical', strength_score: 0.99, explanation: 'The Great Pyramid and the Sphinx are components of the same Giza necropolis complex, built within decades of each other during the Fourth Dynasty. Debates about the relative dating of the Sphinx directly affect interpretations of the Great Pyramid\'s historical context.', evidence_basis: 'Archaeological: the Giza plateau has been extensively excavated and surveyed.', source_type: 'archaeological', confidence_score: 0.99 },
  { id: 'e012', from: 'great-pyramid', to: 'pyramid-construction-debate', relationship_type: 'historical', strength_score: 0.99, explanation: 'The Great Pyramid is the primary subject of all pyramid construction debates. Its scale, precision, and the logistics of its stone supply make it the central case study for both mainstream and alternative engineering analyses.', evidence_basis: 'The Wadi al-Jarf papyri specifically document Great Pyramid construction logistics.', source_type: 'archaeological', confidence_score: 0.99 },
  { id: 'e013', from: 'great-pyramid', to: 'nabta-playa', relationship_type: 'geographical', strength_score: 0.55, explanation: 'Nabta Playa and the Giza complex are both in Egypt and both feature proposed astronomical alignments. Some researchers have proposed cultural continuity between the pre-dynastic astronomical traditions at Nabta Playa and the astronomical alignment of Giza.', evidence_basis: 'Geographic proximity; Bauval\'s research on Egyptian astronomical traditions.', source_type: 'academic', confidence_score: 0.45 },
  { id: 'e014', from: 'great-pyramid', to: 'ancient-megalithic-sites', relationship_type: 'historical', strength_score: 0.8, explanation: 'The Egyptian pyramid tradition is the most sophisticated expression of megalithic construction. The Great Pyramid represents the pinnacle of a development traceable from mastaba tombs through step pyramids to the true pyramid form.', evidence_basis: 'Comparative architecture and engineering; Egyptian pyramid development is well-documented.', source_type: 'archaeological', confidence_score: 0.85 },
  { id: 'e015', from: 'book-of-enoch', to: 'watchers', relationship_type: 'textual', strength_score: 0.99, explanation: 'The Watcher narrative is the core mythological content of the Book of Watchers section (1 Enoch 1–36). The Watchers, their descent, their teachings, and the birth of the Nephilim are the primary subject of this text.', evidence_basis: 'Primary textual: 1 Enoch; Dead Sea Scrolls manuscripts.', source_type: 'primary_text', confidence_score: 0.99 },
  { id: 'e016', from: 'book-of-enoch', to: 'nephilim', relationship_type: 'textual', strength_score: 0.95, explanation: '1 Enoch provides the most detailed account of Nephilim origins in the Jewish textual tradition, describing them as the offspring of the 200 Watchers who descended to Mount Hermon.', evidence_basis: 'Primary textual: 1 Enoch chapters 6–8; Dead Sea Scrolls Book of Giants.', source_type: 'primary_text', confidence_score: 0.97 },
  { id: 'e017', from: 'book-of-enoch', to: 'dead-sea-scrolls', relationship_type: 'historical', strength_score: 0.97, explanation: 'Multiple copies of 1 Enoch were among the most represented texts at Qumran. Fragments from 11 different manuscripts of 1 Enoch were found in Cave 4, making it one of the most copied texts in the collection alongside Psalms and Deuteronomy.', evidence_basis: 'Archaeological: Dead Sea Scrolls inventory; Milik\'s The Books of Enoch (1976).', source_type: 'archaeological', confidence_score: 0.99 },
  { id: 'e018', from: 'book-of-enoch', to: 'flood-narratives', relationship_type: 'textual', strength_score: 0.85, explanation: 'The Book of Enoch presents the Nephilim\'s violence and the Watchers\' corruption of humanity as the direct cause of the biblical flood — God\'s response to the contamination of both human genetics and knowledge.', evidence_basis: '1 Enoch 10–11: Noah\'s flood presented as divine cleansing of Watcher-caused corruption.', source_type: 'primary_text', confidence_score: 0.92 },
  { id: 'e019', from: 'book-of-enoch', to: 'comparative-mythology', relationship_type: 'thematic', strength_score: 0.75, explanation: 'The Watcher narrative in 1 Enoch has structural parallels with Mesopotamian Apkallu traditions, Greek Titan traditions (Prometheus bringing fire to humans), and other "divine teachers" myths.', evidence_basis: 'Comparative religious studies: Kvanvig\'s Roots of Apocalyptic (1988); Annus\'s work on Apkallu traditions.', source_type: 'academic', confidence_score: 0.78 },
  { id: 'e020', from: 'dead-sea-scrolls', to: 'epic-of-gilgamesh', relationship_type: 'thematic', strength_score: 0.55, explanation: 'The Dead Sea Scrolls community showed knowledge of and engagement with Mesopotamian literary traditions. The flood narrative parallels between Genesis (well-represented in the Scrolls) and the Gilgamesh tradition are part of the broader scholarly discussion the scrolls illuminate about biblical source traditions.', evidence_basis: 'Academic: textual comparisons between Genesis manuscripts in the Scrolls and Near Eastern parallels.', source_type: 'academic', confidence_score: 0.6 },
  { id: 'e021', from: 'epic-of-gilgamesh', to: 'flood-narratives', relationship_type: 'textual', strength_score: 0.99, explanation: 'Tablet XI of the Epic of Gilgamesh contains the most complete and detailed Mesopotamian flood narrative, with close structural parallels to Genesis 6–9. The relationship between these Mesopotamian flood texts and the biblical narrative is one of the central questions in biblical studies.', evidence_basis: 'Primary textual: cuneiform tablets from Nineveh\'s Library of Ashurbanipal; academic comparative analysis.', source_type: 'primary_text', confidence_score: 0.99 },
  { id: 'e022', from: 'epic-of-gilgamesh', to: 'comparative-mythology', relationship_type: 'thematic', strength_score: 0.9, explanation: 'The Epic of Gilgamesh is a foundational text in comparative mythology, studied for its parallels with Greek heroic tradition and its exploration of themes (mortality, friendship, hubris) that recur across world literature.', evidence_basis: 'Academic comparative literature: Andrew George\'s The Babylonian Gilgamesh Epic (2003).', source_type: 'academic', confidence_score: 0.92 },
  { id: 'e023', from: 'roswell-incident', to: 'pentagon-uap-reports', relationship_type: 'historical', strength_score: 0.75, explanation: 'The Roswell incident is the foundational event in the modern UFO narrative and the primary cultural frame through which government UAP disclosures are interpreted.', evidence_basis: 'Documented institutional history of U.S. government UFO investigation programs.', source_type: 'historical_record', confidence_score: 0.8 },
  { id: 'e024', from: 'rendlesham-forest', to: 'pentagon-uap-reports', relationship_type: 'historical', strength_score: 0.65, explanation: 'The Rendlesham Forest incident, like the Pentagon UAP reports, involves formal military documentation of unexplained aerial phenomena. Both represent cases where military personnel officially reported encounters with unidentified objects.', evidence_basis: 'Official documentation: Halt memo; Pentagon ODNI UAP preliminary assessment.', source_type: 'historical_record', confidence_score: 0.7 },
  { id: 'e025', from: 'ancient-astronaut-hypothesis', to: 'sumerian-civilization', relationship_type: 'thematic', strength_score: 0.65, explanation: 'The ancient astronaut hypothesis uses Sumerian mythology and iconography as its primary claimed evidence base, particularly Sitchin\'s interpretations of the Anunnaki as extraterrestrial beings.', evidence_basis: 'Sitchin\'s published interpretations; rejected by professional Sumerologists.', source_type: 'academic', confidence_score: 0.4 },
  { id: 'e026', from: 'ancient-astronaut-hypothesis', to: 'great-pyramid', relationship_type: 'thematic', strength_score: 0.6, explanation: 'The Great Pyramid\'s engineering precision and scale are among the most frequently cited pieces of claimed evidence for the ancient astronaut hypothesis.', evidence_basis: 'Popular literature (von Däniken, etc.); mainstream Egyptology provides conventional explanations.', source_type: 'academic', confidence_score: 0.25 },
  { id: 'e027', from: 'human-evolution', to: 'neanderthals', relationship_type: 'historical', strength_score: 0.99, explanation: 'Neanderthals are the best-documented sister species to Homo sapiens. Their interbreeding with modern humans (confirmed by ancient DNA showing 1–4% Neanderthal DNA in non-African populations) represents a key event in human evolutionary history.', evidence_basis: 'Ancient DNA analysis: Pääbo et al. (2010); paleontological record.', source_type: 'scientific', confidence_score: 0.99 },
  { id: 'e028', from: 'human-evolution', to: 'denisovans', relationship_type: 'historical', strength_score: 0.97, explanation: 'Denisovans represent a major archaic human lineage that interbred with modern Homo sapiens, leaving genetic legacy in Melanesian, Aboriginal Australian, and some East Asian populations.', evidence_basis: 'Ancient DNA analysis: Pääbo et al. (2010); subsequent genomic studies.', source_type: 'scientific', confidence_score: 0.97 },
  { id: 'e029', from: 'human-evolution', to: 'human-migration', relationship_type: 'historical', strength_score: 0.97, explanation: 'The Out of Africa migration is the direct consequence of modern human evolution in Africa and their subsequent competitive advantage over archaic populations. The two topics are inseparable.', evidence_basis: 'Genetic and archaeological evidence convergently support African origin and subsequent global dispersal.', source_type: 'scientific', confidence_score: 0.97 },
  { id: 'e030', from: 'human-evolution', to: 'stoned-ape-theory', relationship_type: 'thematic', strength_score: 0.6, explanation: 'The Stoned Ape Theory is explicitly a hypothesis about a mechanism contributing to human cognitive evolution, addressing the same rapid brain size expansion that mainstream paleoanthropology attributes to social complexity, diet, and sexual selection.', evidence_basis: 'McKenna\'s own framing positions the hypothesis within evolutionary biology.', source_type: 'academic', confidence_score: 0.65 },
  { id: 'e031', from: 'neanderthals', to: 'denisovans', relationship_type: 'historical', strength_score: 0.95, explanation: 'Neanderthals and Denisovans are sister lineages — genetically more closely related to each other than either is to modern Homo sapiens. Evidence suggests they also interbred, as indicated by the "Denisova 11" specimen who had a Neanderthal mother and a Denisovan father.', evidence_basis: 'Ancient DNA analysis: Slon et al. (2018) on the Denisova 11 hybrid individual.', source_type: 'scientific', confidence_score: 0.97 },
  { id: 'e032', from: 'simulation-hypothesis', to: 'hard-problem-consciousness', relationship_type: 'thematic', strength_score: 0.75, explanation: 'The simulation hypothesis and the hard problem of consciousness intersect at the question of the nature of subjective experience: if we live in a simulation, the simulation must generate genuine conscious experience.', evidence_basis: 'Philosophical literature: Chalmers, Bostrom, Tegmark; academic philosophy of mind.', source_type: 'academic', confidence_score: 0.7 },
  { id: 'e033', from: 'hard-problem-consciousness', to: 'quantum-consciousness', relationship_type: 'thematic', strength_score: 0.7, explanation: 'Quantum consciousness theories (Orch-OR) are in part motivated by the hard problem — the idea that classical neural computation cannot explain subjective experience, so quantum processes may provide the additional explanatory ingredient.', evidence_basis: 'Penrose\'s The Emperor\'s New Mind (1989) and Shadows of the Mind (1994).', source_type: 'academic', confidence_score: 0.72 },
  { id: 'e034', from: 'hard-problem-consciousness', to: 'collective-unconscious', relationship_type: 'thematic', strength_score: 0.5, explanation: 'Both the hard problem and the collective unconscious concern the nature and scope of consciousness beyond individual subjective experience.', evidence_basis: 'Philosophical and psychological literature; connections drawn in transpersonal psychology.', source_type: 'academic', confidence_score: 0.45 },
  { id: 'e035', from: 'collective-unconscious', to: 'comparative-mythology', relationship_type: 'thematic', strength_score: 0.85, explanation: 'Jung developed the concept of the collective unconscious in large part to explain cross-cultural mythological similarities — the same archetypes appearing in myths of peoples without known historical contact.', evidence_basis: 'Jung\'s Collected Works, particularly The Archetypes and the Collective Unconscious (1959).', source_type: 'academic', confidence_score: 0.87 },
  { id: 'e036', from: 'collective-unconscious', to: 'mystery-schools', relationship_type: 'thematic', strength_score: 0.6, explanation: 'Jung studied ancient mystery schools as historical precedents for the kind of transformative psychological experience he theorized in depth psychology. The initiatory structure of mystery school rituals parallels the individuation process Jung described.', evidence_basis: 'Jung\'s works on religion and alchemy; his documented interest in Eleusis and Mithraic mysteries.', source_type: 'academic', confidence_score: 0.62 },
  { id: 'e037', from: 'freemasonry', to: 'hermeticism', relationship_type: 'influence', strength_score: 0.8, explanation: 'The higher degrees of Freemasonry incorporate Hermetic symbolism, alchemical imagery, and esoteric Kabbalah. Frances Yates and other historians have documented the Hermetic-Rosicrucian influence on Speculative Freemasonry as it developed in the 17th–18th centuries.', evidence_basis: 'Historical scholarship: Yates, The Rosicrucian Enlightenment (1972); Masonic ritual texts.', source_type: 'historical_record', confidence_score: 0.82 },
  { id: 'e038', from: 'freemasonry', to: 'rosicrucianism', relationship_type: 'influence', strength_score: 0.75, explanation: 'The intellectual and esoteric currents of Rosicrucianism demonstrably influenced early Speculative Freemasonry. Cross-membership between Rosicrucian-inspired groups and Masonic lodges in the 17th–18th century is documented.', evidence_basis: 'Frances Yates, The Rosicrucian Enlightenment (1972); historical lodge records.', source_type: 'historical_record', confidence_score: 0.75 },
  { id: 'e039', from: 'rosicrucianism', to: 'hermeticism', relationship_type: 'influence', strength_score: 0.9, explanation: 'The Rosicrucian manifestos explicitly drew on the Hermetic tradition — their program of universal reform combined Hermetic philosophy, alchemy, Kabbalah, and natural philosophy.', evidence_basis: 'Primary textual: the Rosicrucian manifestos themselves (1614–1616).', source_type: 'primary_text', confidence_score: 0.92 },
  { id: 'e040', from: 'hermeticism', to: 'mystery-schools', relationship_type: 'influence', strength_score: 0.85, explanation: 'The Hermetic corpus is a product of Alexandrian synthesis drawing on Egyptian religious traditions, Greek philosophy, and the initiatory religious currents that produced the mystery schools.', evidence_basis: 'Academic: Fowden, The Egyptian Hermes (1986).', source_type: 'academic', confidence_score: 0.82 },
  { id: 'e041', from: 'illuminati-history', to: 'freemasonry', relationship_type: 'historical', strength_score: 0.75, explanation: 'The historical Illuminati recruited significantly from Masonic lodges — Weishaupt initially joined a lodge to access potential members. The two organizations overlapped in personnel and intellectual milieu.', evidence_basis: 'Historical records of Illuminati membership and their Masonic lodge membership.', source_type: 'historical_record', confidence_score: 0.8 },
  { id: 'e042', from: 'bronze-age-collapse', to: 'younger-dryas', relationship_type: 'thematic', strength_score: 0.45, explanation: 'Both the Bronze Age Collapse and the Younger Dryas event are studied as examples of civilization-threatening environmental disruption. Researchers studying systems collapse apply similar frameworks to both events.', evidence_basis: 'Comparative historical and paleoclimatological analysis.', source_type: 'academic', confidence_score: 0.45 },
  { id: 'e043', from: 'bronze-age-collapse', to: 'sumerian-civilization', relationship_type: 'historical', strength_score: 0.7, explanation: 'The Bronze Age Collapse terminated the Kassite dynasty of Babylonia (heirs to Sumerian civilization) and devastated Mesopotamian trade networks, ending the Bronze Age world in which Sumerian cultural influence had spread throughout the Near East.', evidence_basis: 'Archaeological and textual records of the Kassite collapse c. 1155 BCE.', source_type: 'historical_record', confidence_score: 0.72 },
  { id: 'e044', from: 'younger-dryas-impact', to: 'younger-dryas', relationship_type: 'historical', strength_score: 0.85, explanation: 'The Younger Dryas Impact Hypothesis is a proposed causal mechanism for the Younger Dryas climatic event. The hypothesis is specifically an attempt to explain the rapid cooling that defines the Younger Dryas period.', evidence_basis: 'Firestone et al. (2007) PNAS paper proposing the impact trigger; subsequent peer-reviewed debate.', source_type: 'scientific', confidence_score: 0.85 },
  { id: 'e045', from: 'silk-road', to: 'sumerian-civilization', relationship_type: 'historical', strength_score: 0.55, explanation: 'Mesopotamia was a key hub of early long-distance trade networks that would eventually develop into the Silk Road. The lapis lazuli trade from Afghanistan to Sumer documented from c. 3000 BCE represents one of the earliest verified long-distance trade networks.', evidence_basis: 'Archaeological evidence of Afghan lapis lazuli in Sumerian archaeological contexts.', source_type: 'archaeological', confidence_score: 0.6 },
  { id: 'e046', from: 'giants-ancient-texts', to: 'nephilim', relationship_type: 'textual', strength_score: 0.9, explanation: 'The Nephilim of the Hebrew Bible are the central Jewish example of giant beings in ancient texts. The Nephilim/Rephaim/Anakim traditions form the primary textual basis for giant traditions in the Abrahamic religions.', evidence_basis: 'Genesis 6:4; Numbers 13:33; Deuteronomy 3:11; Septuagint translations.', source_type: 'primary_text', confidence_score: 0.9 },
  { id: 'e047', from: 'giants-ancient-texts', to: 'comparative-mythology', relationship_type: 'thematic', strength_score: 0.85, explanation: 'Giant traditions constitute one of the most widely distributed mythological motifs and are studied within comparative mythology as examples of cross-cultural narrative parallels.', evidence_basis: 'Comparative mythology scholarship; Leeming\'s Mythology: The Voyage of the Hero.', source_type: 'academic', confidence_score: 0.85 },
  { id: 'e048', from: 'dragon-traditions', to: 'comparative-mythology', relationship_type: 'thematic', strength_score: 0.9, explanation: 'Dragon and cosmic serpent traditions are among the most studied motifs in comparative mythology. Their near-universal presence makes dragon traditions a central case study for theories of mythological universals versus cross-cultural diffusion.', evidence_basis: 'Jones, An Instinct for Dragons (2000); Witzel, The Origins of the World\'s Mythologies (2012).', source_type: 'academic', confidence_score: 0.9 },
  { id: 'e049', from: 'dragon-traditions', to: 'mystery-schools', relationship_type: 'thematic', strength_score: 0.5, explanation: 'Serpent symbolism is central to many mystery school traditions — the Orphic serpent Phanes, the Nāga in Hindu and Buddhist initiatory contexts, and the Hermetic caduceus. The serpent as a symbol of wisdom connects dragon traditions to esoteric initiatory traditions.', evidence_basis: 'Symbolic analysis in academic study of mystery religions.', source_type: 'academic', confidence_score: 0.52 },
  { id: 'e050', from: 'giants-ancient-texts', to: 'book-of-enoch', relationship_type: 'textual', strength_score: 0.88, explanation: 'The Book of Enoch is the primary ancient text elaborating on the origin and nature of the Nephilim/giants, providing the most detailed account of their parentage (the Watchers), nature, and ultimate fate at the flood.', evidence_basis: '1 Enoch 7–8; 4Q530-532 (Book of Giants) among the Dead Sea Scrolls.', source_type: 'primary_text', confidence_score: 0.88 },
  { id: 'e051', from: 'indus-valley', to: 'silk-road', relationship_type: 'historical', strength_score: 0.7, explanation: 'The Indus Valley Civilization had documented trade connections with Mesopotamia and Central Asia that represent early examples of the long-distance exchange networks that would eventually form the Silk Road.', evidence_basis: 'Archaeological: Indus seals at Ur; Mesopotamian goods in Indus Valley sites.', source_type: 'archaeological', confidence_score: 0.72 },
  { id: 'e052', from: 'human-migration', to: 'younger-dryas', relationship_type: 'historical', strength_score: 0.7, explanation: 'The Younger Dryas cooling severely affected human populations in the Northern Hemisphere, potentially contributing to population decline in North America and Eurasia, and may have played a role in spurring the Neolithic revolution as human groups adapted to changed conditions.', evidence_basis: 'Paleoclimate data correlated with archaeological population records and genomic bottleneck evidence.', source_type: 'scientific', confidence_score: 0.68 },
  { id: 'e053', from: 'easter-island', to: 'human-migration', relationship_type: 'historical', strength_score: 0.85, explanation: 'Easter Island is one of the last inhabited places on Earth to be settled by humans — Polynesian ancestors reached Rapa Nui approximately 1200 CE, representing one of the final chapters of the remarkable human migration that populated the Pacific.', evidence_basis: 'Genetic analysis tracing Polynesian ancestry; radiocarbon dating of earliest Rapa Nui settlement.', source_type: 'scientific', confidence_score: 0.9 },
  { id: 'e054', from: 'antikythera-mechanism', to: 'sumerian-civilization', relationship_type: 'historical', strength_score: 0.6, explanation: 'The Antikythera Mechanism incorporates Babylonian astronomical parameters — particularly its use of the Saros cycle (Babylonian discovery) and the Metonic cycle — demonstrating that Hellenistic Greek astronomy integrated and built on the Babylonian astronomical tradition that originated in Sumer.', evidence_basis: 'Analysis of the Mechanism\'s astronomical parameters: Freeth et al. (2021) in Scientific Reports.', source_type: 'scientific', confidence_score: 0.78 },
  { id: 'e055', from: 'mystery-schools', to: 'stoned-ape-theory', relationship_type: 'thematic', strength_score: 0.55, explanation: 'Both the mystery school tradition and the Stoned Ape Theory involve the use of mind-altering substances to achieve transformative states of consciousness. The proposed kykeon-as-psychedelic hypothesis for the Eleusinian Mysteries directly connects ancient ritual use of psychedelics to the kind of consciousness expansion McKenna proposed.', evidence_basis: 'Wasson, Hofmann, Ruck: The Road to Eleusis (1978); McKenna: Food of the Gods (1992).', source_type: 'academic', confidence_score: 0.52 },

  // ── Contradictory edges — documented academic disagreements ─────────

  { id: 'e056', from: 'ancient-astronaut-hypothesis', to: 'pyramid-construction-debate', relationship_type: 'contradictory', strength_score: 0.90, explanation: 'The ancient astronaut hypothesis claims Egyptian pyramids required external non-human assistance because the engineering was beyond the capability of ancient humans. The pyramid construction evidence base — including the Wadi al-Jarf papyri documenting logistics and the Heit el-Ghurab workers\' village — directly contradicts this, providing documented evidence of conventional human methods.', evidence_basis: 'Feder, Frauds, Myths, and Mysteries (2018); Lehner & Hawass, Giza and the Pyramids (2017); Tallet, Les papyrus de la mer Rouge (2017) — all document the human construction case.', source_type: 'archaeological', confidence_score: 0.92 },

  { id: 'e057', from: 'stoned-ape-theory', to: 'human-evolution', relationship_type: 'contradictory', strength_score: 0.75, explanation: 'McKenna\'s Stoned Ape Theory proposes that psilocybin mushroom consumption was a primary driver of the rapid cognitive evolution of the Homo lineage. Mainstream paleoanthropology and evolutionary biology attribute brain expansion to dietary protein, social complexity, tool use, and sexual selection — mechanisms with substantial empirical support that the mushroom hypothesis does not require and cannot currently account for.', evidence_basis: 'Stringer, Lone Survivors (2012); White et al., Science 326 (2009); mainstream paleoanthropological literature.', source_type: 'scientific', confidence_score: 0.85 },

  { id: 'e058', from: 'sphinx', to: 'pyramid-construction-debate', relationship_type: 'contradictory', strength_score: 0.65, explanation: 'Robert Schoch\'s water erosion hypothesis for the Sphinx implies a construction date potentially predating 5000 BCE — thousands of years before the Fourth Dynasty pyramid-building era documented in the conventional construction timeline. If the Sphinx predates the pyramids by millennia, the integrated construction program of the Giza plateau inferred from pyramid-era papyri and workforce evidence requires fundamental revision.', evidence_basis: 'Schoch, Voices of the Rocks (1999) vs. Gauri et al., Geoarchaeology 10 (1995); Hawass, Secrets of the Sphinx (1998).', source_type: 'archaeological', confidence_score: 0.60 },

  // ── Ancient Stargate Hypothesis edges ────────────────────────────────

  { id: 'e059', from: 'ancient-stargate-hypothesis', to: 'ancient-astronaut-hypothesis', relationship_type: 'thematic', strength_score: 0.80, explanation: 'The Ancient Stargate Hypothesis and the ancient astronaut hypothesis share a common interpretive framework: both treat mythological accounts of supernatural beings, celestial travel, and divine portals as literal descriptions of physical phenomena involving non-human intelligence. Many popular-level proponents of one hypothesis also advocate the other.', evidence_basis: 'Comparative popular literature; both hypotheses originate substantially in reinterpretations of Sumerian and Egyptian texts. No independent physical evidence links them.', source_type: 'academic', confidence_score: 0.68 },
  { id: 'e060', from: 'ancient-stargate-hypothesis', to: 'sumerian-civilization', relationship_type: 'textual', strength_score: 0.72, explanation: 'The Ancient Stargate Hypothesis draws primarily on Sumerian mythological texts, particularly the abzu (primordial waters / netherworld) and the Anunnaki\'s described movements between realms, as claimed evidence for functional portals in ancient Mesopotamia. Professional Sumerologists read these texts as cosmological mythology, not technical description.', evidence_basis: 'Sitchin\'s interpretations of Enuma Elish and Sumerian King List; rejected by mainstream Sumerology (Heiser, Fritze).', source_type: 'primary_text', confidence_score: 0.28 },
  { id: 'e061', from: 'ancient-stargate-hypothesis', to: 'book-of-enoch', relationship_type: 'textual', strength_score: 0.55, explanation: '1 Enoch\'s descriptions of Enoch\'s heavenly ascent — passing through multiple "gates" of heaven corresponding to astronomical phenomena and being transported to the divine throne room — are cited by some researchers as early textual evidence for a portal/gate concept in ancient thought. Mainstream scholarship reads these as literary and visionary cosmology, not physical portals.', evidence_basis: '1 Enoch 33–36 (Astronomical Book); 1 Enoch 14 (Enoch\'s throne-room vision). Academic context: Nickelsburg, 1 Enoch: A Commentary (2001).', source_type: 'primary_text', confidence_score: 0.26 },
  { id: 'e062', from: 'ancient-stargate-hypothesis', to: 'comparative-mythology', relationship_type: 'thematic', strength_score: 0.68, explanation: 'Gate and threshold symbolism — the idea of a passage between earthly and divine realms — is one of the most widely distributed concepts in world religion and mythology: Egyptian Duat gates, Mesopotamian kur, Hindu lokas, and Homeric Elysium all describe structured passage between planes of existence. Comparative mythology maps these as symbolic-cosmological traditions; the stargate hypothesis treats them as literal accounts.', evidence_basis: 'Comparative religious studies: Eliade, The Sacred and the Profane (1959); academic mythology scholarship.', source_type: 'academic', confidence_score: 0.62 },
  { id: 'e063', from: 'ancient-stargate-hypothesis', to: 'watchers', relationship_type: 'textual', strength_score: 0.52, explanation: 'The Watcher tradition in 1 Enoch and the Book of Jubilees describes divine beings descending from and ascending to a celestial realm. Some proponents of the Ancient Stargate Hypothesis cite the Watchers\' described passage between realms as evidence for ancient knowledge of interdimensional or interstellar travel. Mainstream scholarship reads the Watchers as a theological narrative about divine transgression.', evidence_basis: '1 Enoch 6–16; Book of Jubilees 4–5. Academic context: Stuckenbruck, The Book of Giants from Qumran (1997).', source_type: 'primary_text', confidence_score: 0.24 },
  { id: 'e064', from: 'ancient-stargate-hypothesis', to: 'mystery-schools', relationship_type: 'thematic', strength_score: 0.45, explanation: 'Mystery school initiatory traditions — including Eleusis, Orphism, and Egyptian funerary rites — involve symbolic passage through thresholds as a core metaphor for spiritual transformation. Some researchers in the esoteric tradition interpret these initiatory gates as preserved memory of literal stargates. Academic historians of religion treat them as symbolic structures for psychological transformation.', evidence_basis: 'Esoteric literature; academic: Burkert, Ancient Mystery Cults (1987).', source_type: 'academic', confidence_score: 0.20 },
  { id: 'e065', from: 'ancient-stargate-hypothesis', to: 'great-pyramid', relationship_type: 'thematic', strength_score: 0.48, explanation: 'The Great Pyramid is cited by some proponents (including William Henry) as a possible stargate or consciousness portal, based on the ascending and descending passageways, the King\'s Chamber acoustics, and the chamber\'s coffer dimensions. Mainstream Egyptology identifies the structure as a royal tomb with funerary symbolism. No physical mechanism for portal function has been proposed in testable form.', evidence_basis: 'William Henry\'s popular publications; mainstream: Lehner & Hawass, Giza and the Pyramids (2017).', source_type: 'academic', confidence_score: 0.13 },
  { id: 'e066', from: 'ancient-stargate-hypothesis', to: 'gobekli-tepe', relationship_type: 'thematic', strength_score: 0.30, explanation: 'Göbekli Tepe\'s enclosures feature carved pillars with complex iconography that some popular writers have interpreted as representing cosmic portals or dimensional gates. The site\'s deliberate burial c. 8000 BCE has been speculatively described as "portal deactivation." Mainstream archaeology reads the burial as intentional site closure, possibly for ritual reasons or to create an artificial tell; no evidence supports a portal-related interpretation.', evidence_basis: 'Fringe literature; mainstream: Schmidt, Sie bauten die ersten Tempel (2006); Peters & Schmidt in Documenta Praehistorica (2004).', source_type: 'archaeological', confidence_score: 0.08 },

  // ── TEST BATCH 1 EDGES — 2026-06-09 ──

  { id: 'e067', from: 'stonehenge', to: 'ancient-megalithic-sites', relationship_type: 'historical', strength_score: 0.95, explanation: 'Stonehenge is the most extensively studied example of the British megalithic tradition and one of the central case studies in debates about prehistoric astronomical alignment, organized labour, and Neolithic social complexity. Its construction history spans approximately the same broad period as the wider British and European megalithic horizon.', evidence_basis: 'Parker Pearson, Stonehenge: Exploring the Greatest Stone Age Mystery (2012); UNESCO World Heritage designation covers the Stonehenge-Avebury complex together.', source_type: 'archaeological', confidence_score: 0.96 },
  { id: 'e068', from: 'stonehenge', to: 'gobekli-tepe', relationship_type: 'thematic', strength_score: 0.60, explanation: 'Both Stonehenge and Göbekli Tepe are stone monuments built by societies engaged in complex ritual practice, raising comparable questions about the relationship between monumental construction, social organization, and astronomical observation across different cultures. Stonehenge postdates Göbekli Tepe by several thousand years and was built by farming societies rather than hunter-gatherers.', evidence_basis: 'Comparative prehistoric archaeology; both are central case studies in the archaeology of ritual landscapes and early astronomical observation.', source_type: 'archaeological', confidence_score: 0.60 },
  { id: 'e069', from: 'stonehenge', to: 'nabta-playa', relationship_type: 'thematic', strength_score: 0.50, explanation: 'Both Stonehenge and Nabta Playa feature stone monuments with intentional solar alignments built by pre-state societies, raising comparative questions about independent development of astronomical observing traditions across different cultural and geographic zones.', evidence_basis: 'Comparative archaeoastronomy; Aveni, Stairways to the Stars (1997).', source_type: 'archaeological', confidence_score: 0.50 },
  { id: 'e070', from: 'anunnaki', to: 'sumerian-civilization', relationship_type: 'historical', strength_score: 0.99, explanation: 'The Anunnaki are the principal divine assembly of the Sumerian religious system and are documented across Sumerian and Akkadian texts that are the primary literary output of that civilization. The Anunnaki pantheon is central to Sumerian cosmology, temple economy, and political theology.', evidence_basis: 'Primary textual: Sumerian hymns, king lists, Enuma Elish, Atrahasis — all accessible via ETCSL, Oxford.', source_type: 'primary_text', confidence_score: 0.99 },
  { id: 'e071', from: 'anunnaki', to: 'ancient-astronaut-hypothesis', relationship_type: 'thematic', strength_score: 0.72, explanation: 'Zecharia Sitchin\'s ancient astronaut hypothesis is based primarily on his claimed reinterpretation of Sumerian texts referring to the Anunnaki as extraterrestrial beings. His translations have been rejected by every professional Assyriologist who has examined them, but they remain the most widely cited "evidence" in ancient astronaut literature.', evidence_basis: 'Sitchin\'s published works; academic rebuttals: Heiser, sitchiniswrong.com; ETCSL standard translations.', source_type: 'academic', confidence_score: 0.35 },
  { id: 'e072', from: 'anunnaki', to: 'ancient-stargate-hypothesis', relationship_type: 'thematic', strength_score: 0.52, explanation: 'The Ancient Stargate Hypothesis draws heavily on Sumerian cosmological language — including Anunnaki narratives and the abzu — as claimed evidence for ancient portal technology. Mainstream Assyriology interprets the same texts as standard religious cosmology and mythological literature.', evidence_basis: 'William Henry\'s popular publications; mainstream Assyriology rebuttal: Heiser; ETCSL standard translations.', source_type: 'academic', confidence_score: 0.22 },
  { id: 'e073', from: 'project-blue-book', to: 'roswell-incident', relationship_type: 'historical', strength_score: 0.78, explanation: 'Project Blue Book was the Air Force investigation framework operating during the height of post-Roswell UFO public interest. Although the Roswell incident predated Blue Book\'s founding by five years, the program\'s culture and case-handling were shaped by the controversy Roswell generated. J. Allen Hynek later commented on the Roswell case in the context of Blue Book\'s approach to high-profile incidents.', evidence_basis: 'Air Force Blue Book records and institutional history; Hynek, The UFO Experience (1972).', source_type: 'historical_record', confidence_score: 0.72 },
  { id: 'e074', from: 'project-blue-book', to: 'pentagon-uap-reports', relationship_type: 'historical', strength_score: 0.90, explanation: 'Project Blue Book is the direct historical predecessor to modern U.S. government UAP investigation programs. AATIP (2007), the UAP Task Force (2020), and AARO (2022) all operate within an institutional history that begins with Project Sign and Blue Book. The AARO Historical Record Report Vol. 1 (2024) explicitly traces this lineage.', evidence_basis: 'AARO Historical Record Report Vol. 1 (2024), available at aaro.mil; institutional history of U.S. government UAP programs.', source_type: 'historical_record', confidence_score: 0.90 },

  // ── STAGE 2 EDGES — 2026-06-09 ──

  { id: 'e075', from: 'nazca-lines', to: 'ancient-astronaut-hypothesis', relationship_type: 'thematic', strength_score: 0.65, explanation: 'The Nasca lines are among the most frequently cited pieces of claimed evidence in the ancient astronaut hypothesis, with popular proponents arguing the scale and geometry of the geoglyphs implies they were created as runways or signals for extraterrestrial aircraft. Mainstream archaeology attributes the lines to the Nasca culture using simple surveying tools, abundant labor, and religious/ceremonial motivations documented in the archaeological record.', evidence_basis: 'Von Däniken, Chariots of the Gods (1968) — primary ancient astronaut claim; Aveni, Between the Lines (2000) — systematic scholarly refutation demonstrating human-scale production methods.', source_type: 'archaeological', confidence_score: 0.35 },
  { id: 'e076', from: 'nazca-lines', to: 'ancient-megalithic-sites', relationship_type: 'thematic', strength_score: 0.52, explanation: 'The Nasca lines share with megalithic traditions the characteristic of large-scale organized landscape modification requiring coordinated community labor and sustained planning over generations. Both are studied as evidence for pre-state societies\' capacity for complex, long-duration collective projects with apparently ritual or cosmological purposes.', evidence_basis: 'Comparative prehistoric archaeology; Silverman & Proulx, The Nasca (2002).', source_type: 'archaeological', confidence_score: 0.58 },
  { id: 'e077', from: 'library-of-alexandria', to: 'antikythera-mechanism', relationship_type: 'historical', strength_score: 0.68, explanation: 'The Antikythera Mechanism was built in the same Hellenistic intellectual world that the Library of Alexandria sustained. The advanced astronomical knowledge embedded in the Mechanism — including Babylonian eclipse cycles and Greek planetary theory — represents precisely the kind of synthesis the Library\'s scholars pursued. Archimedes and other figures associated with the Library\'s intellectual tradition are sometimes cited in connection with the Mechanism\'s likely origins.', evidence_basis: 'Freeth et al., Nature (2006); MacLeod (ed.), The Library of Alexandria (2000); both document the Hellenistic scientific milieu.', source_type: 'historical_record', confidence_score: 0.62 },
  { id: 'e078', from: 'library-of-alexandria', to: 'hermeticism', relationship_type: 'influence', strength_score: 0.70, explanation: 'Alexandria under the Ptolemies was the birthplace of the Hermetic tradition. The Corpus Hermeticum emerged from the same Alexandrian intellectual environment that the Library sustained — a fusion of Greek philosophy, Egyptian religious thought, and Neoplatonism. The Library\'s role in making Egyptian religious knowledge accessible to Greek-speaking scholars created the conditions for Hermetic synthesis.', evidence_basis: 'Fowden, The Egyptian Hermes (1986); Copenhaver, Hermetica (1992) — both document Alexandria as the crucible of Hermetic philosophy.', source_type: 'historical_record', confidence_score: 0.72 },
  { id: 'e079', from: 'abzu', to: 'anunnaki', relationship_type: 'historical', strength_score: 0.95, explanation: 'The abzu is the cosmic domain of Enki, the Anunnaki god of freshwater, wisdom, and magic. In Sumerian cosmology the abzu is both the physical underground freshwater ocean and Enki\'s sacred temple precinct at Eridu. The Anunnaki\'s cosmic geography is organized around the abzu, the earth, and the heavens — making the abzu inseparable from the Anunnaki theological system.', evidence_basis: 'Primary textual: ETCSL Sumerian hymns to Enki; Black & Green, Gods, Demons and Symbols (1992).', source_type: 'primary_text', confidence_score: 0.97 },
  { id: 'e080', from: 'abzu', to: 'sumerian-civilization', relationship_type: 'historical', strength_score: 0.95, explanation: 'The abzu is a central concept of Sumerian cosmological and religious thought, originating in the sacred city of Eridu — considered by Sumerians the oldest city and the location of the first temple. The concept of the abzu as the source of life-giving freshwater and divine wisdom is embedded in Sumerian temple architecture, ritual practice, and literary tradition from the earliest written records.', evidence_basis: 'Primary textual: Eridu Genesis; ETCSL; Jacobsen, The Treasures of Darkness (1976).', source_type: 'primary_text', confidence_score: 0.97 },
  { id: 'e081', from: 'abzu', to: 'ancient-stargate-hypothesis', relationship_type: 'thematic', strength_score: 0.55, explanation: 'The abzu — Enki\'s cosmic domain accessible from his temple precinct — is cited by proponents of the Ancient Stargate Hypothesis as evidence that ancient Sumerians described functional interdimensional portals. The term abzu has been reinterpreted in popular esoteric literature as encoding knowledge of portal physics. Mainstream Assyriology reads the abzu as standard cosmological mythology describing the freshwater table and Enki\'s ritual domain.', evidence_basis: 'Popular esoteric literature; ETCSL standard translations; Black & Green (1992) — mainstream Assyriological reading.', source_type: 'primary_text', confidence_score: 0.22 },
  { id: 'e082', from: 'church-committee', to: 'mkultra', relationship_type: 'historical', strength_score: 0.95, explanation: 'The Church Committee\'s investigation directly exposed MKUltra to public scrutiny for the first time. CIA Director William Colby\'s testimony before the Committee in 1975, combined with journalist Seymour Hersh\'s 1974 New York Times article, forced the CIA to acknowledge the program. The Church Committee Final Report (1976) contains the definitive congressional account of MKUltra.', evidence_basis: 'Church Committee Final Report Vol. 1 (1976); Church Committee Senate hearing transcripts 1975–1976.', source_type: 'historical_record', confidence_score: 0.98 },
  { id: 'e083', from: 'watergate', to: 'church-committee', relationship_type: 'historical', strength_score: 0.85, explanation: 'The Watergate scandal directly created the political and institutional conditions for the Church Committee. The revelations of executive branch lawlessness and CIA domestic operations exposed during the Watergate investigation motivated the Senate to authorize a comprehensive investigation of the intelligence community. Without the crisis of confidence created by Watergate, the Church Committee\'s sweeping mandate would have been politically impossible.', evidence_basis: 'Congressional record; Johnson, A Season of Inquiry (1985); institutional history of Senate intelligence oversight.', source_type: 'historical_record', confidence_score: 0.90 },
  { id: 'e084', from: 'operation-paperclip', to: 'mkultra', relationship_type: 'historical', strength_score: 0.60, explanation: 'Operation Paperclip and MKUltra share an organizational genealogy: both involved the CIA importing and applying methods developed under Nazi-era research programs. Several German and Austrian scientists recruited under Paperclip had direct connections to wartime human experimentation programs that MKUltra continued in different form. The institutional culture of secret human experimentation as a national security tool connects both programs.', evidence_basis: 'Jacobsen, Operation Paperclip (2014); Marks, The Search for the Manchurian Candidate (1979); overlap in personnel and institutional methods is documented.', source_type: 'historical_record', confidence_score: 0.65 },
  { id: 'e085', from: 'ark-of-covenant', to: 'dead-sea-scrolls', relationship_type: 'historical', strength_score: 0.55, explanation: 'The Dead Sea Scrolls contain texts from the same Second Temple Jewish tradition that venerated the Ark of the Covenant and speculated about its fate after the Babylonian destruction of Solomon\'s Temple. The Temple Scroll (11QT) from Qumran contains detailed instructions for a future Temple that include specifications for the Ark\'s housing. The Copper Scroll has been speculatively linked to hidden Temple vessels including the Ark.', evidence_basis: '11QT (Temple Scroll) — Yadin edition; 3Q15 (Copper Scroll) analysis; academic Dead Sea Scrolls scholarship.', source_type: 'archaeological', confidence_score: 0.52 },
  { id: 'e086', from: 'tower-of-babel', to: 'sumerian-civilization', relationship_type: 'thematic', strength_score: 0.75, explanation: 'The Tower of Babel narrative in Genesis 11 is widely recognized by biblical scholars as a literary reflection of the Babylonian ziggurat tradition, particularly the Etemenanki ziggurat of Babylon ("Foundation of Heaven and Earth") described in cuneiform sources. The biblical narrative appears to encode Israelite encounter with Mesopotamian monumental architecture, possibly during the Babylonian exile.', evidence_basis: 'Speiser, Genesis (Anchor Bible, 1964); Walton, Ancient Near Eastern Thought and the Old Testament (2006); comparative textual analysis.', source_type: 'academic', confidence_score: 0.80 },
  { id: 'e087', from: 'tower-of-babel', to: 'comparative-mythology', relationship_type: 'thematic', strength_score: 0.75, explanation: 'The Tower of Babel narrative is a prominent case study in comparative mythology as an etiological myth — a story explaining the origin of linguistic diversity. Its structural parallels with Mesopotamian cosmological myths about divine-human boundary transgression and subsequent divine judgment make it a key text in discussions of how ancient Near Eastern mythological themes entered the biblical corpus.', evidence_basis: 'Academic comparative mythology and biblical studies; Speiser, Genesis commentary (1964); Walton (2006).', source_type: 'academic', confidence_score: 0.80 },
  { id: 'e088', from: 'tower-of-babel', to: 'flood-narratives', relationship_type: 'textual', strength_score: 0.70, explanation: 'In the Genesis narrative structure, the Tower of Babel episode (Genesis 11) follows immediately after the Table of Nations (Genesis 10) and the flood narrative (Genesis 6–9). Both are presented as pivotal moments in the relationship between humans and the divine, and both reflect the broader ancient Near Eastern literary tradition of catastrophic divine intervention following human transgression. Scholars study the two narratives as parallel etiological traditions.', evidence_basis: 'Genesis 10–11 (Hebrew Bible); comparative textual analysis in the Pentateuch source tradition.', source_type: 'primary_text', confidence_score: 0.72 },
  { id: 'e089', from: 'germ-theory', to: 'black-death', relationship_type: 'historical', strength_score: 0.88, explanation: 'Germ theory is the scientific framework that ultimately explained the Black Death. The 1894 identification of Yersinia pestis by Alexandre Yersin (working in Hong Kong during the Third Plague Pandemic) directly applied germ theory to understand the pathogen responsible for the 14th-century pandemic. Modern ancient DNA analysis confirming Y. pestis in Black Death victims is a direct product of the molecular microbiology that germ theory enabled.', evidence_basis: 'Bos et al., Nature (2011) — aDNA confirmation of Y. pestis; Porter, The Greatest Benefit to Mankind (1997) — historical context.', source_type: 'scientific', confidence_score: 0.92 },
  { id: 'e090', from: 'cia-stargate-project', to: 'ancient-stargate-hypothesis', relationship_type: 'thematic', strength_score: 0.60, explanation: 'The CIA\'s Stargate Project shares its name and thematic framing with the Ancient Stargate Hypothesis — both concern the concept of accessing distant or hidden realms through non-conventional means. Popular authors have drawn connections between the remote viewing protocols developed in Stargate and ancient traditions of shamanic or priestly "far seeing." The name itself was chosen in part for its esoteric resonance with ancient gate symbolism.', evidence_basis: 'CIA Stargate Collection (CREST, 1995); program naming documented in internal CIA memoranda.', source_type: 'historical_record', confidence_score: 0.45 },
  { id: 'e091', from: 'cia-stargate-project', to: 'mkultra', relationship_type: 'historical', strength_score: 0.65, explanation: 'The CIA\'s Stargate Project grew out of the same institutional culture of secret parapsychological and consciousness research that produced MKUltra. Both programs operated under the Science and Technology Directorate and both were motivated by Cold War intelligence competition — in this case, Soviet research into psychotronics. The Church Committee\'s exposure of MKUltra created congressional scrutiny that shaped how Stargate was classified and administered.', evidence_basis: 'CIA Stargate Collection documents; Schnabel, Remote Viewers (1997); institutional history of CIA R&D programs.', source_type: 'historical_record', confidence_score: 0.68 },
  { id: 'e092', from: 'cia-stargate-project', to: 'project-blue-book', relationship_type: 'thematic', strength_score: 0.50, explanation: 'Both Project Blue Book and the CIA\'s Stargate Project represent official U.S. government investigations into phenomena on the boundary of established science — UAP and remote viewing respectively. Both were eventually terminated following independent scientific reviews that found insufficient evidence for the phenomena under investigation, and both generated declassified records that continue to be mined by researchers.', evidence_basis: 'Institutional comparison; Condon Report (1968) on Blue Book; AIR evaluation (1995) on Stargate.', source_type: 'historical_record', confidence_score: 0.52 },
  { id: 'e093', from: 'church-committee', to: 'pentagon-uap-reports', relationship_type: 'thematic', strength_score: 0.45, explanation: 'The Church Committee established the modern framework of congressional intelligence oversight — including requirements for notification of covert programs and oversight mechanisms — within which modern UAP investigations like AATIP and AARO have operated. The committee\'s reforms directly created the classified briefing and Congressional notification structures that became relevant when UAP programs were disclosed after 2017.', evidence_basis: 'AARO Historical Record Report Vol. 1 (2024); Congressional Research Service reports on intelligence oversight history.', source_type: 'historical_record', confidence_score: 0.48 },

  // ── STAGE 3 EDGES — 2026-06-09 ──

  { id: 'e094', from: 'phoenix-lights', to: 'pentagon-uap-reports', relationship_type: 'historical', strength_score: 0.72, explanation: 'The Phoenix Lights mass sighting is one of the most cited events in UAP public discourse and directly contributed to public pressure for government UAP disclosure programs. The scale of credible civilian and official witnessing — including a sitting governor — made Phoenix Lights a benchmark case that later UAP investigators, journalists, and the AARO historical review have acknowledged as among the most significant modern sightings.', evidence_basis: 'AARO Historical Record Report (2024); Leslie Kean, UFOs: Generals, Pilots, and Government Officials Go on the Record (2010) — documents Phoenix Lights in the context of credible UAP cases.', source_type: 'historical_record', confidence_score: 0.72 },
  { id: 'e095', from: 'spanish-flu-1918', to: 'germ-theory', relationship_type: 'historical', strength_score: 0.90, explanation: 'The 1918 influenza pandemic was investigated and is understood entirely through the scientific framework of germ theory. The application of bacteriology and virology to the 1918 outbreak — first attempting to identify a bacterial cause (Pfeiffer\'s bacillus), then recognizing a filterable virus — represents germ theory being actively applied under conditions of maximum public health urgency. The 2005 reconstruction of the 1918 virus genome is a direct product of molecular virology built on germ theory foundations.', evidence_basis: 'Taubenberger et al., Nature (2005); Porter, The Greatest Benefit to Mankind (1997); John Barry, The Great Influenza (2004).', source_type: 'scientific', confidence_score: 0.92 },
  { id: 'e096', from: 'spanish-flu-1918', to: 'covid-19', relationship_type: 'thematic', strength_score: 0.70, explanation: 'The 1918 influenza pandemic is the primary historical benchmark against which the COVID-19 pandemic has been measured throughout the 2020–2023 period. Both the CDC and WHO explicitly reference 1918 in pandemic preparedness frameworks. Specific 1918 lessons — the value of early non-pharmaceutical interventions, the role of political leadership, the danger of premature reopening — were applied (with varying success) to COVID-19 response planning and critique.', evidence_basis: 'CDC pandemic preparedness documentation; WHO, COVID-19: Make it the Last Pandemic (2021); multiple peer-reviewed comparative studies 2020–2023.', source_type: 'historical_record', confidence_score: 0.75 },
  { id: 'e097', from: 'covid-19', to: 'who-organization', relationship_type: 'historical', strength_score: 0.95, explanation: 'WHO declared the COVID-19 pandemic, coordinated the international public health response, led vaccine distribution mechanisms (COVAX), and hosted the international investigations into COVID-19\'s origins. The pandemic is the most consequential test of WHO\'s role as the world\'s central public health coordination body since smallpox eradication, and its handling of COVID-19 has been the subject of the most significant criticism and reform pressure in WHO\'s history.', evidence_basis: 'WHO COVID-19 situation reports; Independent Panel for Pandemic Preparedness and Response (2021); WHO Constitutional authority under IHR 2005.', source_type: 'historical_record', confidence_score: 0.97 },
  { id: 'e098', from: 'covid-19', to: 'germ-theory', relationship_type: 'historical', strength_score: 0.97, explanation: 'SARS-CoV-2\'s causation of COVID-19 was established entirely within the framework of germ theory and its molecular extensions: isolation of the virus, genomic sequencing, reproduction of disease in animal models, and development of virus-targeted vaccines and antivirals. All COVID-19 science — from diagnostics through treatment through vaccination — operates within the germ theory paradigm.', evidence_basis: 'Zhu et al., NEJM (2020) — initial virus isolation paper; all subsequent COVID-19 science operates within germ theory framework.', source_type: 'scientific', confidence_score: 0.99 },
  { id: 'e099', from: 'covid-19', to: 'covid-19-origin-debate', relationship_type: 'historical', strength_score: 0.99, explanation: 'The COVID-19 origin debate is directly and specifically about the emergence of SARS-CoV-2, the causative agent of COVID-19. The two nodes are inseparable: the origin question only has significance in the context of the pandemic, and the pandemic\'s scale makes the origin question consequential for biosafety policy, international relations, and pandemic preparedness.', evidence_basis: 'All scientific and intelligence assessments on the origin debate are contingent on COVID-19\'s pandemic-scale significance.', source_type: 'historical_record', confidence_score: 0.99 },
  { id: 'e100', from: 'covid-19', to: 'vaccine-history', relationship_type: 'historical', strength_score: 0.92, explanation: 'COVID-19 prompted the fastest vaccine development in history and represents the operational debut of the mRNA vaccine platform at scale. The COVID-19 mRNA vaccines — Pfizer/BioNTech BNT162b2 and Moderna mRNA-1273 — are a landmark in vaccine development history, with the Nobel Prize in Physiology or Medicine 2023 awarded to Karikó and Weissman for the foundational mRNA technology these vaccines deployed.', evidence_basis: 'Nobel Prize in Physiology or Medicine 2023 announcement; Polack et al. NEJM (2020) — Pfizer phase 3 trial paper; Baden et al. NEJM (2020) — Moderna phase 3 trial paper.', source_type: 'scientific', confidence_score: 0.95 },
  { id: 'e101', from: 'smallpox-eradication', to: 'who-organization', relationship_type: 'historical', strength_score: 0.96, explanation: 'WHO designed, funded, coordinated, and certified the global eradication of smallpox — the organization\'s single greatest achievement. The Intensified Eradication Programme (1967–1980) is the model for WHO\'s emergency health coordination capacity, and the WHO\'s May 8, 1980 certification of eradication remains the definitive official act recognizing the program\'s success.', evidence_basis: 'Fenner et al., Smallpox and its Eradication (WHO, 1988); WHO WHA33.3 resolution (1980) certifying eradication.', source_type: 'historical_record', confidence_score: 0.98 },
  { id: 'e102', from: 'smallpox-eradication', to: 'vaccine-history', relationship_type: 'historical', strength_score: 0.95, explanation: 'Smallpox is the bookend of vaccine history: Edward Jenner\'s 1796 smallpox vaccine was the first vaccine ever developed; smallpox eradication in 1980 was the ultimate demonstration of vaccines\' disease-elimination potential. The vaccine development history from Jenner through the 20th century is substantially a history of building on and extending the smallpox vaccination paradigm.', evidence_basis: 'Jenner, An Inquiry into the Causes and Effects of the Variolae Vaccinae (1798); Fenner et al. (1988).', source_type: 'historical_record', confidence_score: 0.97 },
  { id: 'e103', from: 'hiv-aids', to: 'who-organization', relationship_type: 'historical', strength_score: 0.88, explanation: 'WHO coordinates global HIV/AIDS response through UNAIDS (the Joint United Nations Programme on HIV/AIDS, co-sponsored by WHO and established in 1996). WHO\'s treatment guidelines, surveillance systems, and access-to-medicines advocacy have been central to the global HIV response, and HIV/AIDS remains one of WHO\'s largest programmatic areas.', evidence_basis: 'UNAIDS Global AIDS Update 2023; WHO HIV/AIDS programme documentation; WHO Global Health Observatory data.', source_type: 'historical_record', confidence_score: 0.88 },
  { id: 'e104', from: 'hiv-aids', to: 'germ-theory', relationship_type: 'historical', strength_score: 0.88, explanation: 'HIV was identified as the causative agent of AIDS through direct application of the germ theory paradigm — isolation of a retrovirus, demonstration of its presence in AIDS patients, and subsequent fulfilment of modified Koch\'s postulates through animal model studies. All HIV/AIDS medicine, from diagnostics through antiretroviral treatment to vaccine research, operates within the germ theory framework.', evidence_basis: 'Barré-Sinoussi et al., Science (1983) — primary HIV isolation paper; Montagnier\'s Nobel Lecture (2008).', source_type: 'scientific', confidence_score: 0.95 },
  { id: 'e105', from: 'vaccine-history', to: 'germ-theory', relationship_type: 'historical', strength_score: 0.93, explanation: 'Modern vaccine development is theoretically inseparable from germ theory: the concept that specific microorganisms cause specific diseases provides the rationale for developing immunological defences against specific pathogens. Pasteur\'s articulation of germ theory and his development of the first laboratory vaccines (cholera, anthrax, rabies) represent a single unified scientific program. The mRNA vaccine platform is a molecular extension of the same theoretical foundation.', evidence_basis: 'Porter, The Greatest Benefit to Mankind (1997); Plotkin\'s Vaccines (8th ed., 2023) — the standard vaccinology reference.', source_type: 'scientific', confidence_score: 0.97 },
  { id: 'e106', from: 'jeffrey-epstein', to: 'ghislaine-maxwell', relationship_type: 'historical', strength_score: 0.99, explanation: 'Ghislaine Maxwell is documented in court records and by jury verdict as Jeffrey Epstein\'s primary associate and active participant in his trafficking network. Their relationship lasted from the early 1990s through his 2019 arrest. Maxwell\'s conviction specifically found her guilty of facilitating Epstein\'s crimes across multiple properties.', evidence_basis: 'United States v. Ghislaine Maxwell, S2 20 Cr. 330 (AJN), SDNY — jury verdict December 29, 2021; sentencing June 28, 2022.', source_type: 'historical_record', confidence_score: 0.99 },
  { id: 'e107', from: 'jeffrey-epstein', to: 'little-saint-james', relationship_type: 'historical', strength_score: 0.97, explanation: 'Little Saint James Island is documented in court records and victim testimony as Jeffrey Epstein\'s primary property for trafficking operations, with victims describing travel to the island and abuse occurring there. The island was specifically named in the USVI civil litigation and in victim accounts corroborated at the Maxwell trial.', evidence_basis: 'Victim testimony in Maxwell trial proceedings; USVI v. Epstein Estate civil litigation; Giuffre v. Maxwell civil case records.', source_type: 'historical_record', confidence_score: 0.97 },
  { id: 'e108', from: 'jeffrey-epstein', to: 'epstein-flight-logs', relationship_type: 'historical', strength_score: 0.97, explanation: 'The flight logs document travel aboard Epstein\'s private aircraft to and from his various properties, directly corroborating victim accounts of how Epstein transported people within his network. The logs are primary documents in the Epstein case record.', evidence_basis: 'Court records in Giuffre v. Maxwell, SDNY; court order by Judge Loretta Preska unsealing documents (January 2024).', source_type: 'historical_record', confidence_score: 0.97 },
  { id: 'e109', from: 'ghislaine-maxwell', to: 'little-saint-james', relationship_type: 'historical', strength_score: 0.88, explanation: 'Ghislaine Maxwell is documented through victim testimony and court proceedings as having been present at Little Saint James and as facilitating trafficking operations there. Victim accounts corroborated at trial describe Maxwell\'s role in activities at the island.', evidence_basis: 'Victim testimony in United States v. Maxwell (2021); civil case records in Giuffre v. Maxwell.', source_type: 'historical_record', confidence_score: 0.90 },
  { id: 'e110', from: 'pentagon-papers', to: 'watergate', relationship_type: 'historical', strength_score: 0.75, explanation: 'The Pentagon Papers leak directly caused Nixon\'s creation of the "Plumbers" special investigations unit — the same covert group that later executed the Watergate break-in. Nixon\'s response to the Ellsberg leak, including illegal wiretapping and the break-in at Ellsberg\'s psychiatrist\'s office, established the pattern of executive abuse that culminated in Watergate. Both events are expressions of the same Nixon-era crisis of executive power and secrecy.', evidence_basis: 'Ellsberg, Secrets (2002); Senate Watergate Committee Final Report (1974); historical scholarship on the Nixon presidency.', source_type: 'historical_record', confidence_score: 0.85 },
  { id: 'e111', from: 'pentagon-papers', to: 'church-committee', relationship_type: 'historical', strength_score: 0.60, explanation: 'The Pentagon Papers and the subsequent Watergate crisis together created the political climate and institutional impetus for the Church Committee. The Senate\'s 1975 mandate to investigate intelligence community abuses was directly shaped by the revelations of executive secrecy and abuse documented from the Pentagon Papers through Watergate. Ellsberg\'s illegal wiretapping — itself a documented intelligence abuse — was later part of the broader pattern the Church Committee investigated.', evidence_basis: 'Johnson, A Season of Inquiry (1985); historical scholarship on Senate intelligence oversight 1975–1976.', source_type: 'historical_record', confidence_score: 0.62 },
  { id: 'e112', from: 'pleiades-seven-sisters', to: 'comparative-mythology', relationship_type: 'thematic', strength_score: 0.88, explanation: 'The Pleiades\' near-universal cultural significance is one of the most extensively studied cases in comparative mythology and archaeoastronomy. The cluster\'s appearance across independent traditions — Greek, Japanese, Māori, multiple Aboriginal Australian traditions, Mesoamerican, Amazonian, Hindu — makes it a key dataset for theories about independent invention versus cultural diffusion and for claims about the deep antiquity of human astronomical knowledge.', evidence_basis: 'Comparative mythology scholarship including Witzel, Origins of the World\'s Mythologies (2012); archaeoastronomical research by Duane Hamacher and others on Aboriginal Australian Pleiades traditions.', source_type: 'academic', confidence_score: 0.88 },
  { id: 'e113', from: 'pleiades-seven-sisters', to: 'subaru-pleiades', relationship_type: 'historical', strength_score: 0.97, explanation: 'The Subaru automotive brand directly and explicitly derives its name and logo from the Japanese name for the Pleiades — Subaru (昴). The logo depicts the Pleiades cluster as visible to the naked eye. This is the most globally recognized commercial application of the Pleiades\' deep cultural significance in Japanese astronomical tradition.', evidence_basis: 'Subaru Corporation official corporate history; documented Japanese astronomical tradition of the 28 lunar mansions.', source_type: 'historical_record', confidence_score: 0.98 },
  { id: 'e114', from: 'covid-19-origin-debate', to: 'who-organization', relationship_type: 'thematic', strength_score: 0.75, explanation: 'WHO led and convened the primary international investigations into COVID-19\'s origins — the WHO-China joint study team (2021) and the proposed WHO Scientific Advisory Group for the Origins of Novel Pathogens (SAGO). WHO\'s access constraints, procedural decisions, and public communications regarding the origin question have been central subjects in the debate itself, with WHO Director-General Tedros publicly acknowledging that the joint study\'s conclusions were limited by data access.', evidence_basis: 'WHO-China Joint Study Report (2021); WHO DG Tedros public statement March 30, 2021; SAGO terms of reference documents.', source_type: 'historical_record', confidence_score: 0.75 },

  // ── AUDIT FIX: bridge isolated Disease/Pandemic cluster to main graph ──
  { id: 'e115', from: 'black-death', to: 'silk-road', relationship_type: 'historical', strength_score: 0.90, explanation: 'The Black Death reached Europe via the Silk Road: Yersinia pestis traveled west from Central Asian reservoir populations along trade routes, reaching the Crimean port of Caffa in 1346 and arriving in Sicily via Genoese trading ships in 1347. The plague\'s westward trajectory directly followed the overland Silk Road network and its associated maritime extensions, making Silk Road trade the vector for the pandemic\'s entry into Western Europe.', evidence_basis: 'Wheelis, "Biological Warfare at the 1346 Siege of Caffa," Emerging Infectious Diseases (2002); Schmid et al., PNAS (2015) — phylogeographic analysis of Y. pestis tracing its Silk Road dispersal.', source_type: 'historical_record', confidence_score: 0.92 },
  { id: 'e116', from: 'germ-theory', to: 'human-evolution', relationship_type: 'thematic', strength_score: 0.78, explanation: 'Germ theory and evolutionary biology are unified in the field of evolutionary medicine: pathogens are among the strongest selective pressures on human immune system evolution, and the archaeological and genomic record of ancient infectious disease (aDNA studies of Y. pestis, M. tuberculosis, and others) is interpreted through the dual framework of germ theory and natural selection. Pathogen-driven selection has shaped major human genetic variants including HLA alleles, CCR5-delta32, and sickle cell trait.', evidence_basis: 'Tishkoff et al., Science (2001) on sickle cell selection; Sabeti et al., Nature (2002) on CCR5-delta32 and plague; evolutionary medicine: Nesse & Williams, Why We Get Sick (1994).', source_type: 'academic', confidence_score: 0.82 },

  // ── AUDIT FIX: bridge isolated Epstein cluster to main graph ──
  { id: 'e117', from: 'jeffrey-epstein', to: 'watergate', relationship_type: 'thematic', strength_score: 0.55, explanation: 'The Epstein case and Watergate are both studied as instances of powerful networks operating above legal accountability with the apparent complicity of government institutions. Common analytical themes include prosecutorial failures (the 2008 non-prosecution agreement echoes the pardoning of Nixon\'s co-conspirators), the role of media in eventual exposure, and the question of whether elite connected individuals receive structurally different treatment from the legal system.', evidence_basis: 'Thematic connection in political science literature on elite accountability and institutional corruption; not a direct historical link.', source_type: 'academic', confidence_score: 0.48 },
  { id: 'e118', from: 'epstein-flight-logs', to: 'pentagon-papers', relationship_type: 'thematic', strength_score: 0.52, explanation: 'The Epstein flight logs and the Pentagon Papers are both examples of documentary evidence whose court-ordered unsealing transformed public understanding of powerful institutions. Both cases involved sustained legal battles over disclosure, government (or powerful private) resistance to release, and ultimately judicial orders compelling transparency. Both sets of documents remain primary sources for ongoing historical investigation into the conduct of powerful actors.', evidence_basis: 'Thematic comparison in journalism and legal scholarship on document disclosure and institutional accountability.', source_type: 'academic', confidence_score: 0.45 },
];
